VALUES ('e4000000-0000-4000-8000-999999999992', 'e4000000-0000-4000-8000-999999999991', 'onet-careers', '30.4', '9a22f020a76d5070d56e53476b0f28102b4b5260c5dab10e9789c53e6ad11b5b', 64, 'published', '{"status":"validated","normalization":"OI divided by 7","ncoMappings":"reviewed exact-title subset only"}'::jsonb, '2026-08-05T00:00:00Z', '2026-08-05T00:00:00Z', NULL)
