WITH source_data(id, onet_code, nco_code, slug, title, description, domain_code) AS (VALUES
  ('e4000000-0000-4000-8000-000000000001'::uuid, '15-2051.00', NULL, 'data-scientists', 'Data Scientists', 'Develop and implement a set of techniques or analytics applications to transform raw data into meaningful information using data-oriented programming languages and visualization software. Apply data mining, data modeling, natural language processing, and machine learning to extract and analyze information from large structured and unstructured datasets. Visualize, interpret, and report data findings. May create dynamic data reports.', 'technology'),
  ('e4000000-0000-4000-8000-000000000002'::uuid, '15-1252.00', '2512.0204', 'software-developers', 'Software Developers', 'Research, design, and develop computer and network software or specialized utility programs. Analyze user needs and develop software solutions, applying principles and techniques of computer science, engineering, and mathematical analysis. Update software or enhance existing software capabilities. May work with computer hardware engineers to integrate hardware and software systems, and develop specifications and performance requirements. May maintain databases within an application area, working individually or coordinating database development as part of a team.', 'technology'),
  ('e4000000-0000-4000-8000-000000000003'::uuid, '17-2051.00', '2142.0100', 'civil-engineers', 'Civil Engineers', 'Perform engineering duties in planning, designing, and overseeing construction and maintenance of building structures and facilities, such as roads, railroads, airports, bridges, harbors, channels, dams, irrigation projects, pipelines, power plants, and water and sewage systems.', 'engineering'),
  ('e4000000-0000-4000-8000-000000000004'::uuid, '17-2141.00', '2144.0100', 'mechanical-engineers', 'Mechanical Engineers', 'Perform engineering duties in planning and designing tools, engines, machines, and other mechanically functioning equipment. Oversee installation, operation, maintenance, and repair of equipment such as centralized heat, gas, water, and steam systems.', 'engineering'),
  ('e4000000-0000-4000-8000-000000000005'::uuid, '29-1123.00', '2264.0100', 'physical-therapists', 'Physical Therapists', 'Assess, plan, organize, and participate in rehabilitative programs that improve mobility, relieve pain, increase strength, and improve or correct disabling conditions resulting from disease or injury.', 'healthcare'),
  ('e4000000-0000-4000-8000-000000000006'::uuid, '29-2011.00', '3212.0701', 'medical-and-clinical-laboratory-technologists', 'Medical and Clinical Laboratory Technologists', 'Perform complex medical laboratory tests for diagnosis, treatment, and prevention of disease. May train or supervise staff.', 'healthcare'),
  ('e4000000-0000-4000-8000-000000000007'::uuid, '25-2021.00', '2341.0400', 'elementary-school-teachers-except-special-education', 'Elementary School Teachers, Except Special Education', 'Teach academic and social skills to students at the elementary school level.', 'education'),
  ('e4000000-0000-4000-8000-000000000008'::uuid, '25-2031.00', NULL, 'secondary-school-teachers-except-special-and-career-technical-education', 'Secondary School Teachers, Except Special and Career/Technical Education', 'Teach one or more subjects to students at the secondary school level.', 'education'),
  ('e4000000-0000-4000-8000-000000000009'::uuid, '13-2011.00', NULL, 'accountants-and-auditors', 'Accountants and Auditors', 'Examine, analyze, and interpret accounting records to prepare financial statements, give advice, or audit and evaluate statements prepared by others. Install or advise on systems of recording costs or other financial and budgetary data.', 'business-finance'),
  ('e4000000-0000-4000-8000-000000000010'::uuid, '13-2051.00', NULL, 'financial-and-investment-analysts', 'Financial and Investment Analysts', 'Conduct quantitative analyses of information involving investment programs or financial data of public or private institutions, including valuation of businesses.', 'business-finance'),
  ('e4000000-0000-4000-8000-000000000011'::uuid, '17-2021.00', NULL, 'agricultural-engineers', 'Agricultural Engineers', 'Apply knowledge of engineering technology and biological science to agricultural problems concerned with power and machinery, electrification, structures, soil and water conservation, and processing of agricultural products.', 'agriculture-environment'),
  ('e4000000-0000-4000-8000-000000000012'::uuid, '19-2041.00', NULL, 'environmental-scientists-and-specialists-including-health', 'Environmental Scientists and Specialists, Including Health', 'Conduct research or perform investigation for the purpose of identifying, abating, or eliminating sources of pollutants or hazards that affect either the environment or public health. Using knowledge of various scientific disciplines, may collect, synthesize, study, report, and recommend action based on data derived from measurements or observations of air, food, soil, water, and other sources.', 'agriculture-environment'),
  ('e4000000-0000-4000-8000-000000000013'::uuid, '47-2111.00', NULL, 'electricians', 'Electricians', 'Install, maintain, and repair electrical wiring, equipment, and fixtures. Ensure that work is in accordance with relevant codes. May install or service street lights, intercom systems, or electrical control systems.', 'skilled-trades'),
  ('e4000000-0000-4000-8000-000000000014'::uuid, '51-4121.00', NULL, 'welders-cutters-solderers-and-brazers', 'Welders, Cutters, Solderers, and Brazers', 'Use hand-welding, flame-cutting, hand-soldering, or brazing equipment to weld or join metal components or to fill holes, indentations, or seams of fabricated metal products.', 'skilled-trades'),
  ('e4000000-0000-4000-8000-000000000015'::uuid, '27-1024.00', NULL, 'graphic-designers', 'Graphic Designers', 'Design or create graphics to meet specific commercial or promotional needs, such as packaging, displays, or logos. May use a variety of mediums to achieve artistic or decorative effects.', 'arts-media-design'),
  ('e4000000-0000-4000-8000-000000000016'::uuid, '27-3043.00', NULL, 'writers-and-authors', 'Writers and Authors', 'Originate and prepare written material, such as scripts, stories, advertisements, and other material.', 'arts-media-design'),
  ('e4000000-0000-4000-8000-000000000017'::uuid, '23-1011.00', NULL, 'lawyers', 'Lawyers', 'Represent clients in criminal and civil litigation and other legal proceedings, draw up legal documents, or manage or advise clients on legal transactions. May specialize in a single area or may practice broadly in many areas of law.', 'law-public-service'),
  ('e4000000-0000-4000-8000-000000000018'::uuid, '33-2011.00', NULL, 'firefighters', 'Firefighters', 'Control and extinguish fires or respond to emergency situations where life, property, or the environment is at risk. Duties may include fire prevention, emergency medical service, hazardous material response, search and rescue, and disaster assistance.', 'law-public-service'),
  ('e4000000-0000-4000-8000-000000000019'::uuid, '19-2031.00', NULL, 'chemists', 'Chemists', 'Conduct qualitative and quantitative chemical analyses or experiments in laboratories for quality or process control or to develop new products or knowledge.', 'science-research'),
  ('e4000000-0000-4000-8000-000000000020'::uuid, '19-1022.00', NULL, 'microbiologists', 'Microbiologists', 'Investigate the growth, structure, development, and other characteristics of microscopic organisms, such as bacteria, algae, or fungi. Includes medical microbiologists who study the relationship between organisms and disease or the effects of antibiotics on microorganisms.', 'science-research'),
  ('e4000000-0000-4000-8000-000000000021'::uuid, '13-1081.00', NULL, 'logisticians', 'Logisticians', 'Analyze and coordinate the ongoing logistical functions of a firm or organization. Responsible for the entire life cycle of a product, including acquisition, distribution, internal allocation, delivery, and final disposal of resources.', 'logistics-operations'),
  ('e4000000-0000-4000-8000-000000000022'::uuid, '11-3071.00', NULL, 'transportation-storage-and-distribution-managers', 'Transportation, Storage, and Distribution Managers', 'Plan, direct, or coordinate transportation, storage, or distribution activities in accordance with organizational policies and applicable government laws or regulations. Includes logistics managers.', 'logistics-operations'),
  ('e4000000-0000-4000-8000-000000000023'::uuid, '35-1011.00', NULL, 'chefs-and-head-cooks', 'Chefs and Head Cooks', 'Direct and may participate in the preparation, seasoning, and cooking of salads, soups, fish, meats, vegetables, desserts, or other foods. May plan and price menu items, order supplies, and keep records and accounts.', 'hospitality-tourism'),
  ('e4000000-0000-4000-8000-000000000024'::uuid, '11-9081.00', NULL, 'lodging-managers', 'Lodging Managers', 'Plan, direct, or coordinate activities of an organization or department that provides lodging and other accommodations.', 'hospitality-tourism'),
  ('e4000000-0000-4000-8000-000000000025'::uuid, '21-1021.00', NULL, 'child-family-and-school-social-workers', 'Child, Family, and School Social Workers', 'Provide social services and assistance to improve the social and psychological functioning of children and their families and to maximize the family well-being and the academic functioning of children. May assist parents, arrange adoptions, and find foster homes for abandoned or abused children. In schools, they address such problems as teenage pregnancy, misbehavior, and truancy. May also advise teachers.', 'social-community'),
  ('e4000000-0000-4000-8000-000000000026'::uuid, '21-1012.00', NULL, 'educational-guidance-and-career-counselors-and-advisors', 'Educational, Guidance, and Career Counselors and Advisors', 'Advise and assist students and provide educational and vocational guidance services.', 'social-community'),
  ('e4000000-0000-4000-8000-000000000027'::uuid, '17-1011.00', NULL, 'architects-except-landscape-and-naval', 'Architects, Except Landscape and Naval', 'Plan and design structures, such as private residences, office buildings, theaters, factories, and other structural property.', 'architecture-construction'),
  ('e4000000-0000-4000-8000-000000000028'::uuid, '11-9021.00', NULL, 'construction-managers', 'Construction Managers', 'Plan, direct, or coordinate, usually through subordinate supervisory personnel, activities concerned with the construction and maintenance of structures, facilities, and systems. Participate in the conceptual development of a construction project and oversee its organization, scheduling, budgeting, and implementation. Includes managers in specialized construction fields, such as carpentry or plumbing.', 'architecture-construction'),
  ('e4000000-0000-4000-8000-000000000029'::uuid, '47-2231.00', '7421.1401', 'solar-photovoltaic-installers', 'Solar Photovoltaic Installers', 'Assemble, install, or maintain solar photovoltaic (PV) systems on roofs or other structures in compliance with site assessment and schematics. May include measuring, cutting, assembling, and bolting structural framing and solar modules. May perform minor electrical work such as current checks.', 'renewable-energy'),
  ('e4000000-0000-4000-8000-000000000030'::uuid, '49-9081.00', NULL, 'wind-turbine-service-technicians', 'Wind Turbine Service Technicians', 'Inspect, diagnose, adjust, or repair wind turbines. Perform maintenance on wind turbine equipment including resolving electrical, mechanical, and hydraulic malfunctions.', 'renewable-energy'),
  ('e4000000-0000-4000-8000-000000000031'::uuid, '49-3023.00', NULL, 'automotive-service-technicians-and-mechanics', 'Automotive Service Technicians and Mechanics', 'Diagnose, adjust, repair, or overhaul automotive vehicles.', 'transport-automotive'),
  ('e4000000-0000-4000-8000-000000000032'::uuid, '53-2011.00', NULL, 'airline-pilots-copilots-and-flight-engineers', 'Airline Pilots, Copilots, and Flight Engineers', 'Pilot and navigate the flight of fixed-wing aircraft, usually on scheduled air carrier routes, for the transport of passengers and cargo. Requires Federal Air Transport certificate and rating for specific aircraft type used. Includes regional, national, and international airline pilots and flight instructors of airline pilots.', 'transport-automotive')
)
